def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    p = int(input_data[1])
    A = []
    idx = 2
    zeros = []
    for i in range(N):
        row = []
        for j in range(N):
            val = int(input_data[idx])
            row.append(val)
            if val == 0:
                zeros.append((i, j))
            idx += 1
        A.append(row)

    K = len(zeros)
    if K == 0:
        # If no zeros, return A^p mod p, which is A mod p
        for row in A:
            print(*(val % p for val in row))
        return

    if p == 2:
        # If p=2, (p-1)^K = 1. Zeros become 1.
        for i in range(N):
            row = []
            for j in range(N):
                if A[i][j] == 0:
                    row.append(1)
                else:
                    row.append(A[i][j] % 2)
            print(*row)
    else:
        # If p > 2, (p-1)^K = (-1)^K.
        # Fixed positions A_ij contribute (-1)^K * A_ij.
        # Zero positions contribute 0 mod p.
        factor = 1 if (K % 2 == 0) else -1
        for i in range(N):
            row = []
            for j in range(N):
                if A[i][j] == 0:
                    row.append(0)
                else:
                    row.append((factor * A[i][j]) % p)
            print(*row)

