    dist = [[-1 for _ in range(N)] for _ in range(N)]
    queue = deque()

    # Base case: length 0 (i to i)
    for i in range(N):
        dist[i][i] = 0
        queue.append((i, i))

    # Base case: length 1 (edges)
    for i in range(N):
        for j in range(N):
            if adj[i][j] != '-':
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    queue.append((i, j))

    # Precompute incoming edges for efficiency
    rev_adj = [[] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if adj[i][j] != '-':
                rev_adj[j].append((i, adj[i][j]))

    while queue:
        u, v = queue.popleft()
        d = dist[u][v]

        # Try to expand: find i -> u and v -> j with same label
        for i, char_iu in rev_adj[u]:
            for j in range(N):
                if adj[v][j] == char_iu:
                    if dist[i][j] == -1:
                        dist[i][j] = d + 2
                        queue.append((i, j))

