from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    adj_matrix = input_data[1:]

    # Pre-process edges
    # rev_adj[v] = [(u, char), ...]
    # out_adj[u][char] = [v, ...]
    rev_adj = [[] for _ in range(N)]
    out_adj = [[[] for _ in range(26)] for _ in range(N)]

    for i in range(N):
        for j in range(N):
            char = adj_matrix[i][j]
            if char != '-':
                val = ord(char) - ord('a')
                rev_adj[j].append((i, val))
                out_adj[i][val].append(j)

    dist = [[-1 for _ in range(N)] for _ in range(N)]
    queue = deque()

    # Base case: length 0
    for i in range(N):
        dist[i][i] = 0
        queue.append((i, i))

    # Base case: length 1
    for i in range(N):
        for char_val in range(26):
            for j in out_adj[i][char_val]:
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    queue.append((i, j))

    # BFS
    while queue:
        u, v = queue.popleft()
        d = dist[u][v]

        # Expand: find i -> u and v -> j with same label
        # To keep it efficient, iterate over incoming edges to u
        for i, char_val in rev_adj[u]:
            # For this character, find all j such that v -> j has this label
            for j in out_adj[v][char_val]:
                if dist[i][j] == -1:
                    dist[i][j] = d + 2
                    queue.append((i, j))

    for row in dist:
        print(*(row))

