import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    a = list(map(int, input_data[1:]))

    def get_max_for_offset(offset):
        # We look at pairs (a[i], a[i+1]) starting from 'offset'
        # i.e., (a[offset], a[offset+1]), (a[offset+2], a[offset+3]), ...
        tokens = []
        for i in range(offset, n - 1, 2):
            if a[i] == a[i+1]:
                tokens.append(a[i])
            else:
                tokens.append(-1)

        # Now find the longest subarray of unique tokens (excluding -1)
        max_len = 0
        start = 0
        seen = {}
        for end in range(len(tokens)):
            val = tokens[end]
            if val == -1:
                seen = {}
                start = end + 1
                continue

            while val in seen:
                del seen[tokens[start]]
                start += 1

            seen[val] = True
            max_len = max(max_len, (end - start + 1) * 2)
        return max_len

    # Check both even and odd starting alignments
    ans = max(get_max_for_offset(0), get_max_for_offset(1))
    print(ans)

solve()

