def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])
    A = list(map(int, input_data[2:2+N]))
    B = list(map(int, input_data[2+N:2+N+M]))

    # Segment tree to store the minimum value of A in a range
    size = 1
    while size < N:
        size *= 2
    tree = [float('inf')] * (2 * size)
    for i in range(N):
        tree[size + i] = A[i]
    for i in range(size - 1, 0, -1):
        tree[i] = min(tree[2 * i], tree[2 * i + 1])

    results = []
    for b in B:
        # Find the first index i such that A[i] <= b
        if tree[1] > b:
            results.append("-1")
        else:
            curr = 1
            while curr < size:
                if tree[2 * curr] <= b:
                    curr = 2 * curr
                else:
                    curr = 2 * curr + 1
            results.append(str(curr - size + 1))

    sys.stdout.write("\n".join(results) + "\n")

