import sys
import math

def solve():
    try:
        line = sys.stdin.readline()
        if not line:
            return
        n = int(line.strip())
    except ValueError:
        return

    limit = int(math.isqrt(n))

    # Sieve of Eratosthenes up to sqrt(N)
    primes = []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    # Count Case 1: p^8 <= N  => p <= N^(1/8)
    count = 0
    for p in primes:
        if p**8 <= n:
            count += 1
        else:
            break

    # Count Case 2: p1^2 * p2^2 <= N  => p1 < p2 and p2 <= sqrt(N)/p1
    # We need to count primes p2 such that p1 < p2 <= sqrt(N)/p1
    # Use binary search (bisect_right) on primes list
    from bisect import bisect_right

    for i in range(len(primes)):
        p1 = primes[i]
        if p1 * p1 >= math.isqrt(n):
            break

        max_p2 = math.isqrt(n) // p1
        # Count primes in (p1, max_p2]
        idx_start = i + 1
        idx_end = bisect_right(primes, max_p2)

        if idx_end > idx_start:
            count += (idx_end - idx_start)

    print(count)

solve()

