    phi = list(range(MAX_A))
    for i in range(2, MAX_A):
        if phi[i] == i:
            for j in range(i, MAX_A, i):
                phi[j] -= phi[j] // i

    # Precompute divisors
    divs = [[] for _ in range(MAX_A)]
    for i in range(1, MAX_A):
        for j in range(i, MAX_A, i):
            divs[j].append(i)

    cnt = [0] * MAX_A
    current_S = 0
    out = []

    for x in A:
        # Calculate sum of gcd(B_k, x) for all previous subsequences
        added = 0
        for d in divs[x]:
            added = (added + phi[d] * cnt[d]) % MOD

        current_S = (2 * current_S + added) % MOD
        out.append(current_S)

        # Update cnt[d] for all divisors of x
        for d in divs[x]:
            cnt[d] = (2 * cnt[d] + 1) % MOD

    sys.stdout.write('\n'.join(map(str, out)) + '\n')

