def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    k = int(input_data[0])
    s = input_data[1]
    t = input_data[2]

    n, m = len(s), len(t)

    # If the length difference is greater than K, it's impossible
    if abs(n - m) > k:
        print("No")
        return

    # dp[j] will store the edit distance for the current row i
    # We only care about columns j such that |i - j| <= k
    # To save space, we use a dictionary or a relative indexing array
    # Since K is small, we can use a list of size 2*K + 1

    # prev_dp[offset] where offset = j - i + K
    # current row i, column j: offset = j - i + K

    # Initialize: dp[j] = j for i=0
    # Range of j is [max(0, i-k), min(m, i+k)]

    prev_dp = {}
    for j in range(k + 1):
        if j <= m:
            prev_dp[j] = j

    for i in range(1, n + 1):
        curr_dp = {}
        start = max(0, i - k)
        end = min(m, i + k)

        for j in range(start, end + 1):
            res = float('inf')
            # Deletion: dp[i-1][j]
            if (i - 1, j) in prev_dp:
                res = min(res, prev_dp[(i - 1, j)] + 1)
            # Insertion: dp[i][j-1]
            if (i, j - 1) in curr_dp:
                res = min(res, curr_dp[(i, j - 1)] + 1)
            # Substitution: dp[i-1][j-1]
            if (i - 1, j - 1) in prev_dp:
                cost = 0 if s[i-1] == t[j-1] else 1
                res = min(res, prev_dp[(i - 1, j - 1)] + cost)

            if res <= k:
                curr_dp[(i, j)] = res
        prev_dp = curr_dp

    if prev_dp.get((n, m), float('inf')) <= k:
        print("Yes")
    else:
        print("No")

