    floor_cells = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == '.':
                floor_cells.append((r, c))

    num_floors = len(floor_cells)
    max_humidified = 0

    # Iterate through all pairs of floor cells to place humidifiers
    for i in range(num_floors):
        for j in range(i + 1, num_floors):
            r1, c1 = floor_cells[i]
            r2, c2 = floor_cells[j]

            count = 0
            # Check every floor cell to see if it's within distance D
            for r, c in floor_cells:
                dist1 = abs(r - r1) + abs(c - c1)
                dist2 = abs(r - r2) + abs(c - c2)

                if dist1 <= d or dist2 <= d:
                    count += 1

            if count > max_humidified:
                max_humidified = count

    print(max_humidified)

if __name__ == '__main__':
