import sys

def solve():
    n, x, y = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    # Identify indices that can be part of a 0^X or 1^Y block
    can_be_0x = [False] * n
    for i in range(n - x + 1):
        if all(s[j] == '0' for j in range(i, i + x)):
            for j in range(i, i + x): can_be_0x[j] = True

    can_be_1y = [False] * n
    for i in range(n - y + 1):
        if all(s[j] == '1' for j in range(i, i + y)):
            for j in range(i, i + y): can_be_1y[j] = True

    # Any character not part of a block must be identical
    for i in range(n):
        if not (can_be_0x[i] or can_be_1y[i]):
            if s[i] != t[i]:
                print("No")
                return

    # Check if the multiset of 0^X and 1^Y blocks are the same
    # We can use a greedy approach to extract blocks since the relative order 
    # of different block types doesn't matter, only the counts.
    def get_blocks(string):
        zeros = 0
        ones = 0
        i = 0
        while i < n:
            if i <= n - x and string[i:i+x] == '0' * x:
                zeros += 1
                i += x
            elif i <= n - y and string[i:i+y] == '1' * y:
                ones += 1
                i += y
            else:
                i += 1
        return zeros, ones

    if get_blocks(s) == get_blocks(t):
        print("Yes")
    else:
        print("No")

