    components = []
    balance = 0
    start = 0
    for i in range(n):
        if s[i] == '(':
            balance += 1
        else:
            balance -= 1

        if balance == 0:
            components.append(s[start:i+1])
            start = i + 1

    from collections import Counter
    counts = Counter(components)

    MOD = 998244353

    def factorial(n):
        res = 1
        for i in range(2, n + 1):
            res = (res * i) % MOD
        return res

    def power(a, b):
        res = 1
        a %= MOD
        while b > 0:
            if b % 2 == 1:
                res = (res * a) % MOD
            a = (a * a) % MOD
            b //= 2
        return res

    def modInverse(n):
        return power(n, MOD - 2)

    k = len(components)
    num = factorial(k)
    den = 1
    for count in counts.values():
        den = (den * factorial(count)) % MOD

    ans = (num * modInverse(den)) % MOD
    print(ans)

