def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    Q = int(input_data[1])
    queries = [int(x) for x in input_data[2:]]

    # The number of fixed elements K for an N x N matrix is given by
    # the set of values (N-2k)^2 + 2k for 0 <= k <= N/2.
    possible_k = set()
    for k in range(N // 2 + 1):
        val = (N - 2 * k) ** 2 + 2 * k
        possible_k.add(val)
        # Also include 0 as per sample 1, which happens when N is even and k=N/2
        if (N - 2 * k) == 0:
            possible_k.add(0)

    for q in queries:
        if q in possible_k:
            print("Yes")
        else:
            print("No")

