import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    Q = int(input_data[1])
    queries = [int(x) for x in input_data[2:]]

    # The set of possible counts of fixed elements K.
    # K = N^2 is always possible (e.g., identity matrix or all 0s).
    # K = 0 is always possible for N >= 2.
    # Other values are of the form N^2 - 2*x*y where 1 <= x, y and x+y <= N.

    possible_k = {0, N * N}
    for x in range(1, N):
        for y in range(1, N - x + 1):
            possible_k.add(N * N - 2 * x * y)

    for k in queries:
        if k in possible_k:
            print("Yes")
        else:
            print("No")

if __name__ == '__main__':
    solve()

