def solve():
    # Use fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    K = int(input_data[1])
    A = [int(x) for x in input_data[2:]]

    MAX_A = 1000000
    freq = [0] * (MAX_A + 1)
    for x in A:
        freq[x] += 1

    # multiples_count[g] will store how many A_j are multiples of g
    multiples_count = [0] * (MAX_A + 1)
    for g in range(1, MAX_A + 1):
        for multiple in range(g, MAX_A + 1, g):
            multiples_count[g] += freq[multiple]

    # best_gcd_for_val[v] stores the largest g such that g|v and multiples_count[g] >= K
    best_gcd_for_val = [0] * (MAX_A + 1)

