        if multiples_count[g] >= K:
            for v in range(g, MAX_A + 1, g):
                if g > best_gcd_for_val[v]:
                    best_gcd_for_val[v] = g

    # Generate output
    results = [str(best_gcd_for_val[x]) for x in A]
    sys.stdout.write('\n'.join(results) + '\n')

