import sys

def solve():
    N, M, K = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(M):
        edges.append(list(map(int, sys.stdin.readline().split())))

    # Max possible distance is N-1
    # Check if distance >= d is possible
    def check(d):
        if d == 0: return True
        # We need to pick K edges such that every path of length < d 
        # contains at least one edge of weight 1.
        # This is equivalent to: min edges to pick to make shortest path >= d
        # Since N is small, we can use brute force or flow if possible.
        # Given constraints, we can use recursion with memoization.
        import itertools
        for combo in itertools.combinations(range(M), K):
            adj = [[float('inf')] * (N + 1) for _ in range(N + 1)]
            for i in range(M):
                u, v = edges[i]
                w = 1 if i in combo else 0
                adj[u][v] = min(adj[u][v], w)

            # Floyd-Warshall
            dist = [row[:] for row in adj]
            for i in range(1, N + 1): dist[i][i] = 0
            for k in range(1, N + 1):
                for i in range(1, N + 1):
                    for j in range(1, N + 1):
                        dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

            if dist[1][N] >= d:
                return True
        return False

    ans = 0
    for d in range(N):
        if check(d):
            ans = d
        else:
            break
    print(ans)

solve()

