    dist = [[float('inf')] * w for _ in range(h)]
    dist[start[0]][start[1]] = 0

    # Deque for 0-1 BFS
    queue = deque([start])

    dr = [-1, 1, 0, 0]
    dc = [0, 0, -1, 1]

    while queue:
        r, c_curr = queue.popleft()

        if (r, c_curr) == end:
