import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    grid = [list(row) for row in input_data[1:]]

    # Process layers sequentially from i = 0 to N/2 - 1
    for i in range(N // 2):
        k = N - 2 * i
        # Extract the current layer's elements
        # The layer consists of the boundary of the subgrid from (i, i) to (N-1-i, N-1-i)
        temp = []
        # Top row
        for j in range(i, N - i):
            temp.append(grid[i][j])
        # Right column
        for r in range(i + 1, N - i):
            temp.append(grid[r][N - 1 - i])
        # Bottom row
        for j in range(N - 2 - i, i - 1, -1):
            temp.append(grid[N - 1 - i][j])
        # Left column
        for r in range(N - 2 - i, i, -1):
            temp.append(grid[r][i])

        # The rotation shifts elements in the boundary.
        # A 90-degree clockwise rotation shifts elements by k-1 positions.
        # Length of the perimeter is 4*(k-1).
        shift = k - 1
        new_layer = [None] * len(temp)
        for idx in range(len(temp)):
            new_layer[(idx + shift) % len(temp)] = temp[idx]

        # Put the rotated elements back into the grid
        idx = 0
        for j in range(i, N - i):
            grid[i][j] = new_layer[idx]; idx += 1
        for r in range(i + 1, N - i):
            grid[r][N - 1 - i] = new_layer[idx]; idx += 1
        for j in range(N - 2 - i, i - 1, -1):
            grid[N - 1 - i][j] = new_layer[idx]; idx += 1
        for r in range(N - 2 - i, i, -1):
            grid[r][i] = new_layer[idx]; idx += 1

    for row in grid:
        print("".join(row))

