import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    N = int(input_data[0])
    Q = int(input_data[1])

    def dist(a, b):
        d = abs(a - b)
        return min(d, N - d)

    # dp[x] = min cost where the hand not specified by H_i is at x
    # Initially L=1, R=2.
    # Instruction 0:
    h0, t0 = input_data[2], int(input_data[3])
    dp = {}
    if h0 == 'L':
        # L is at t0, R is at x
        for x in range(1, N + 1):
            if x != t0:
                dp[x] = dist(1, t0) + dist(2, x)
    else:
        # R is at t0, L is at x
        for x in range(1, N + 1):
            if x != t0:
                dp[x] = dist(2, t0) + dist(1, x)

    curr_h, curr_t = h0, t0

    for i in range(1, Q):
        h, t = input_data[2 + 2*i], int(input_data[3 + 2*i])
        new_dp = {}

        if h == curr_h:
            cost_inc = dist(curr_t, t)
            for x, val in dp.items():
                if x != t:
                    new_dp[x] = val + cost_inc
        else:
            # Moving the hand that was at curr_t to t
            # The hand that was at x stays at x
            # So new "other" is curr_t
            min_val = float('inf')
            for x, val in dp.items():
                if x == t: continue
                cost = val + dist(x, t)
                new_dp[x] = cost
                if val < min_val:
                    min_val = val
            new_dp[curr_t] = min_val

        dp = new_dp
        curr_h, curr_t = h, t

    print(min(dp.values()))

solve()

