import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    edges = input_data[1:]

    nodes = set()
    out_degree = {chr(i + ord('A')): 0 for i in range(26)}
    in_degree = {chr(i + ord('A')): 0 for i in range(26)}
    adj = {chr(i + ord('A')): [] for i in range(26)}

    for s in edges:
        u, v = s[0], s[1]
        out_degree[u] += 1
        in_degree[v] += 1
        adj[u].append(v)
        adj[v].append(u)
        nodes.add(u)
        nodes.add(v)

    visited = set()
    total_paths = 0

    for node in nodes:
        if node not in visited:
            # Find component using BFS
            component = []
            queue = [node]
            visited.add(node)
            while queue:
                u = queue.pop(0)
                component.append(u)
                for v in adj[u]:
                    if v not in visited:
                        visited.add(v)
                        queue.append(v)

            # Calculate paths for this component
            diff_sum = 0
            has_edge = False
            for v in component:
                if out_degree[v] > in_degree[v]:
                    diff_sum += (out_degree[v] - in_degree[v])
                if out_degree[v] > 0 or in_degree[v] > 0:
                    has_edge = True

            if diff_sum == 0:
                # Eulerian circuit case: needs 1 path
                if has_edge:
                    total_paths += 1
            else:
                # Path decomposition case
                total_paths += diff_sum

    print(total_paths)

