import sys

def solve():
    line1 = sys.stdin.readline().split()
    if not line1: return
    n, m = map(int, line1)
    s = sys.stdin.readline().strip()

    MOD = 998244353

    # Precompute transitions: state -> (char_index -> next_state)
    # A state is a tuple (l1, l2, ..., ln)
    # We can represent this as a bitmask of length N where the i-th bit
    # is 1 if l_i > l_{i-1} (with l_0=0).
    # Actually, a simpler representation is just the tuple.

    memo_trans = {}

    def get_next_state(state, char):
        state_key = (state, char)
        if state_key in memo_trans:
            return memo_trans[state_key]

        new_state = [0] * n
        prev_l = 0
        for i in range(n):
            if s[i] == char:
                new_state[i] = prev_l + 1
            else:
                new_state[i] = max(state[i], (new_state[i-1] if i > 0 else 0))
            prev_l = state[i]

        res = tuple(new_state)
        memo_trans[state_key] = res
        return res

    # dp[state] = count
    dp = {tuple([0] * n): 1}

    for _ in range(m):
        new_dp = {}
        for state, count in dp.items():
            for char_code in range(26):
                char = chr(ord('a') + char_code)
                next_st = get_next_state(state, char)
                new_dp[next_st] = (new_dp.get(next_st, 0) + count) % MOD
        dp = new_dp

    ans = [0] * (n + 1)
    for state, count in dp.items():
        ans[state[-1]] = (ans[state[-1]] + count) % MOD

    print(*(ans))

solve()
